class Flux3ActionPreprocessStage(PipelineStage):
    """Observation dict -> canvas, state and prompt."""

    def __init__(self, config: Flux3ActionPipelineConfig):
        super().__init__()
        self.config = config

    def forward(self, batch: Req, server_args: ServerArgs) -> Req:
        start = time.perf_counter()
        state = vla_state(batch)
        if batch.is_warmup:
            state["flux3_observation"] = _warmup_observation(self.config)
        else:
            observation = dict(state.get("observation") or {})
            observation.setdefault("prompt", batch.prompt)
            state["flux3_observation"] = parse_observation(observation, self.config)
        vla_timings(batch)["preprocess_ms"] = (time.perf_counter() - start) * 1000
        return batch


class Flux3ActionTextEncodingStage(PipelineStage):
    """Prompt (and CFG negative) -> DiT-encoded text contexts, cached per caption."""

    def __init__(
        self,
        config: Flux3ActionPipelineConfig,
        transformer: Flux3Transformer,
        text_encoder: Flux3TextEncoder,
    ):
        super().__init__()
        self.config = config
        self.transformer = transformer
        self.text_encoder = text_encoder
        self._contexts: OrderedDict[str, Flux3SegmentState] = OrderedDict()
        self._cached_tokens = 0

    def component_uses(
        self, server_args: ServerArgs, stage_name: str | None = None
    ) -> list[ComponentUse]:
        stage_name = self._component_stage_name(stage_name)
        # Contexts are cached per caption: both components run only on a miss.
        return [
            ComponentUse(
                stage_name=stage_name,
                component_name=name,
                allow_prefetch=False,
                start_at_stage_entry=False,
            )
            for name in ("text_encoder", "transformer")
        ]

    def _encode(self, captions: list[str], device: torch.device) -> dict:
        with self.use_declared_component(
            component_name="text_encoder", module=self.text_encoder
        ):
            # One caption per forward: batching changes bf16 GEMM results.
            encoded = [self.text_encoder.encode([c])[0] for c in captions]
        contexts = {}
        with (
            self.use_declared_component(
                component_name="transformer", module=self.transformer
            ),
            set_forward_context(current_timestep=0, attn_metadata=None),
        ):
            for caption, ctx in zip(captions, encoded):
                contexts[caption] = self.transformer.encode_context(
                    ctx=ctx.to(device), ctx_ids=text_ids(ctx.shape[1]).to(device)
                )
        return contexts

    def _contexts_for(
        self, captions: list[str], device: torch.device, *, use_cache: bool
    ) -> tuple[list[Flux3SegmentState], bool]:
        """DiT-encoded text contexts of ``captions`` and whether all were cached."""
        cached = self._contexts if use_cache else {}
        todo = [c for c in dict.fromkeys(captions) if c not in cached]
        fresh = self._encode(todo, device) if todo else {}
        contexts = [fresh.get(c) or cached[c] for c in captions]
        if use_cache:
            self._remember(captions, fresh)
        return contexts, not todo

    def _remember(
        self, captions: list[str], fresh: dict[str, Flux3SegmentState]
    ) -> None:
        for caption, context in fresh.items():
            self._contexts[caption] = context
            self._cached_tokens += context.length
        for caption in captions:
            self._contexts.move_to_end(caption)
        while (
            self._cached_tokens > self.config.caption_cache_max_tokens
            and self._contexts
        ):
            _, evicted = self._contexts.popitem(last=False)
            self._cached_tokens -= evicted.length

    def forward(self, batch: Req, server_args: ServerArgs) -> Req:
        start = time.perf_counter()
        state = vla_state(batch)
        observation: Flux3ActionObservation = state["flux3_observation"]
        options = vla_options(batch)
        guidance = self.config.resolve_guidance(
            options.get("guidance_scale"), options.get("guidance_scale_action")
        )
        captions = [observation.prompt]
        if any(g != 1.0 for g in guidance.values()):
            captions.append("")
        use_cache = bool(options.get("enable_prefix_cache", True))
        state["flux3_contexts"], hit = self._contexts_for(
            captions, get_local_torch_device(), use_cache=use_cache
        )
        state["flux3_guidance"] = guidance
        state["cache"] = {
            "enabled": use_cache,
            "hit": hit,
            "scope": "caption",
            "mode": "exact",
        }
        vla_timings(batch)["text_ms"] = (time.perf_counter() - start) * 1000
        return batch


class Flux3ActionObservationEncodingStage(PipelineStage):
    """Observed frame (VAE) and robot state -> DiT-encoded conditioning streams."""

    def __init__(
        self,
        config: Flux3ActionPipelineConfig,
        transformer: Flux3Transformer,
        vae: Flux3VideoVAE,
        use_cuda_graph: bool = False,
    ):
        super().__init__()
        self.config = config
        self.transformer = transformer
        self.vae = vae
        self._graph = VLATensorGraphRunner(
            "FLUX 3 observation",
            enabled=use_cuda_graph,
            max_entries=config.cuda_graph_max_entries,
        )

    def component_uses(
        self, server_args: ServerArgs, stage_name: str | None = None
    ) -> list[ComponentUse]:
        stage_name = self._component_stage_name(stage_name)
        return [
            ComponentUse(stage_name=stage_name, component_name="vae"),
            ComponentUse(
                stage_name=stage_name,
                component_name="transformer",
                start_at_stage_entry=False,
            ),
        ]

    def _state_tokens(self, state: torch.Tensor, device: torch.device):
        cfg = self.config
        flipped = _flip_gripper(state, dims=cfg.gripper_flip_dims)
        token = normalize(
            flipped, stats=cfg.state_normalization, clip=cfg.normalization_clip
        )
        values = (token[None, :, None] * cfg.action_scale).to(device)
        return pack_action(values, seconds=torch.zeros(1))

    def _encode_frame(self, frame: torch.Tensor) -> torch.Tensor:
        h, w = self.config.latent_hw
        latent = self.vae.encode_frame(frame)[..., :h, :w]
        return rearrange(latent, "b c t h w -> b (t h w) c")

    def _encode_streams(
        self,
        video: torch.Tensor,
        frame_ids: torch.Tensor,
        action: torch.Tensor,
        action_ids: torch.Tensor,
        zero: torch.Tensor,
    ) -> tuple[torch.Tensor, ...]:
        video_cond = self.transformer.encode_stream(
            name="video_cond", x=video, ids=frame_ids, timesteps=zero
        )
        action_cond = self.transformer.encode_stream(
            name=f"{self.config.action_modality}_cond",
            x=action,
            ids=action_ids,
            timesteps=zero,
        )
        return (*_state_tensors(video_cond), *_state_tensors(action_cond))

    def _encode(self, frame: torch.Tensor, *stream_inputs: torch.Tensor):
        return self._encode_streams(self._encode_frame(frame), *stream_inputs)

    def _vae_use(self):
        return self.use_declared_component(component_name="vae", module=self.vae)

    def _transformer_use(self):
        return self.use_declared_component(
            component_name="transformer", module=self.transformer
        )

    def forward(self, batch: Req, server_args: ServerArgs) -> Req:
        start = time.perf_counter()
        cfg = self.config
        device = get_local_torch_device()
        state = vla_state(batch)
        observation: Flux3ActionObservation = state["flux3_observation"]
        h, w = cfg.latent_hw
        frame_ids = video_ids(frames=1, h=h, w=w, first_frame=0, fps=cfg.fps)
        action, action_ids = self._state_tokens(observation.state, device)
        frame = observation.canvas.to(device, torch.bfloat16)[None]
        stream_inputs = (
            frame_ids.to(device),
            action,
            action_ids.to(device),
            torch.zeros(1, device=device),
        )
        forward_context = set_forward_context(current_timestep=0, attn_metadata=None)
        if self._graph.enabled:
            # Both components are resident whenever graphs are enabled.
            with self._vae_use(), self._transformer_use(), forward_context:
                captured = self._graph.run(self._encode, (frame, *stream_inputs))
                # Replays overwrite the outputs; the states outlive this request.
                tensors = tuple(t.clone() for t in captured)
        else:
            with self._vae_use():
                video = self._encode_frame(frame)
            with self._transformer_use(), forward_context:
                tensors = self._encode_streams(video, *stream_inputs)
        state["flux3_conditioning"] = _states_from_tensors(
            ["video_cond", f"{cfg.action_modality}_cond"], tensors
        )
        vla_timings(batch)["observation_ms"] = (time.perf_counter() - start) * 1000
        return batch


class Flux3ActionDenoisingStage(PipelineStage):
    """Joint video + action flow matching from noise; stores the action chunk."""

    def __init__(
        self,
        config: Flux3ActionPipelineConfig,
        transformer: Flux3Transformer,
        scheduler: FlowUniPCMultistepScheduler,
        use_cuda_graph: bool = False,
    ):
        super().__init__()
        self.config = config
        self.transformer = transformer
        self.scheduler = scheduler
        self._graph = VLATensorGraphRunner(
            "FLUX 3 denoise",
            enabled=use_cuda_graph,
            max_entries=config.cuda_graph_max_entries,
        )

    def component_uses(
        self, server_args: ServerArgs, stage_name: str | None = None
    ) -> list[ComponentUse]:
        return [
            ComponentUse(
                stage_name=self._component_stage_name(stage_name),
                component_name="transformer",
                phase="denoise",
                preferred_ready_after_request=True,
                memory_intensive=True,
            )
        ]

    def _noised_streams(self, seed: int):
        cfg = self.config
        h, w = cfg.latent_hw
        # Latent frames 1.. of the (chunk + 1)-frame window.
        n_pred = cfg.action_horizon // TEMPORAL_DOWNSAMPLE
        # Draw order (video, then action) on a CPU generator matches the reference.
        rng = torch.Generator().manual_seed(seed)
        video_noise = torch.randn(1, LATENT_CHANNELS, n_pred, h, w, generator=rng)
        action_noise = torch.randn(1, cfg.action_dim, cfg.action_horizon, generator=rng)
        video, video_ids = pack_video(video_noise, first_frame=1, fps=cfg.fps)
        seconds = (torch.arange(cfg.action_horizon).float() + 1) / cfg.fps
        action, action_ids = pack_action(action_noise, seconds=seconds)
        return {"video": video, cfg.action_modality: action}, {
            "video": video_ids,
            cfg.action_modality: action_ids,
        }

    def _target_streams(
        self,
        samples: tuple[torch.Tensor, ...],
        ropes: tuple[torch.Tensor, ...],
        t: torch.Tensor,
        *,
        order: list[str],
    ) -> list[Flux3SegmentState]:
        """Noised ``video`` and action streams through their mode blocks."""
        return [
            self.transformer.encode_stream(
                name=name,
                x=x.to(torch.bfloat16),
                ids=None,
                timesteps=t,
                rope=rope,
            )
            for name, x, rope in zip(order, samples, ropes, strict=True)
        ]

    def _denoise_pass(
        self,
        context: Flux3SegmentState,
        targets: list[Flux3SegmentState],
        conditioning: list[Flux3SegmentState],
        *,
        order: list[str],
    ) -> tuple[torch.Tensor, ...]:
        video, action = targets
        video_cond, action_cond = conditioning
        # Joint sequence order: video, video_cond, action, action_cond.
        out = self.transformer.denoise(
            context=context,
            streams=[video, video_cond, action, action_cond],
            targets=order,
        )
        return tuple(out[k] for k in order)

    def _denoise_step(
        self,
        video: torch.Tensor,
        action: torch.Tensor,
        t: torch.Tensor,
        video_rope: torch.Tensor,
        action_rope: torch.Tensor,
        *states: torch.Tensor,
        order: list[str],
        state_names: list[str],
    ) -> tuple[torch.Tensor, ...]:
        """Every CFG pass of one step, flattened; ``states`` = conditioning + contexts."""
        video_cond, action_cond, *contexts = _states_from_tensors(state_names, states)
        targets = self._target_streams(
            (video, action), (video_rope, action_rope), t, order=order
        )
        return tuple(
            p
            for ctx in contexts
            for p in self._denoise_pass(
                ctx, targets, [video_cond, action_cond], order=order
            )
        )

    def forward(self, batch: Req, server_args: ServerArgs) -> Req:
        cfg = self.config
        device = get_local_torch_device()
        state = vla_state(batch)
        observation: Flux3ActionObservation = state["flux3_observation"]
        contexts: list[Flux3SegmentState] = state["flux3_contexts"]
        conditioning: list[Flux3SegmentState] = state["flux3_conditioning"]
        guidance: dict[str, float] = state["flux3_guidance"]
        steps = batch.num_inference_steps
        seed = batch.seed[0] if isinstance(batch.seed, list) else batch.seed
        horizon = batch.action_horizon or cfg.action_horizon
        if horizon > cfg.action_horizon:
            raise ValueError(
                f"action_horizon {horizon} exceeds the policy chunk {cfg.action_horizon}"
            )

        start = time.perf_counter()
        samples, ids = self._noised_streams(seed)
        samples = {k: v.to(device) for k, v in samples.items()}
        order = list(samples)
        ropes = tuple(self.transformer.rope(ids[k].to(device)) for k in order)
        cfg_policy = _cfg_parallel_policy(contexts, server_args)
        state_names = [s.name for s in (*conditioning, *contexts)]
        states = tuple(t for s in (*conditioning, *contexts) for t in _state_tensors(s))
        denoise_step = functools.partial(
            self._denoise_step, order=order, state_names=state_names
        )
        step = 0

        def predict(
            current: dict[str, torch.Tensor], t: float
        ) -> dict[str, torch.Tensor]:
            nonlocal step
            timestep = torch.full((1,), t, device=device, dtype=torch.float32)
            current_streams = tuple(current[k] for k in order)
            with set_forward_context(
                current_timestep=step, attn_metadata=None, forward_batch=batch
            ):
                if cfg_policy is not None:
                    targets = self._target_streams(
                        current_streams, ropes, timestep, order=order
                    )
                    # Each rank runs one branch; all ranks get both predictions.
                    raw = run_cfg_parallel(
                        cfg_policy,
                        lambda branch: self._denoise_pass(
                            branch.kwargs["context"],
                            targets,
                            conditioning,
                            order=order,
                        ),
                    )
                else:
                    flat = self._graph.run(
                        denoise_step,
                        (*current_streams, timestep, *ropes, *states),
                        key=(tuple(order), tuple(state_names)),
                    )
                    raw = [
                        flat[i : i + len(order)]
                        for i in range(0, len(flat), len(order))
                    ]
                preds = [dict(zip(order, p)) for p in raw]
            step += 1
            if len(preds) == 1:
                return {k: v.float() for k, v in preds[0].items()}
            cond, uncond = preds
            return {
                k: (uncond[k] + guidance[k] * (cond[k] - uncond[k])).float()
                for k in order
            }

        with self.use_declared_component(
            component_name="transformer", module=self.transformer
        ):
            result = cosmos_unipc(
                samples,
                predict,
                scheduler=self.scheduler,
                n_steps=steps,
                shift=cfg.sampler_shift,
            )
        targets = result[cfg.action_modality][0].float() / cfg.action_scale
        actions = targets_to_actions(
            targets, state=observation.state.to(device), config=cfg
        )
        state["actions"] = actions[None, :horizon]
        synchronize_vla_action_tensor(actions)
        vla_timings(batch)["denoise_ms"] = (time.perf_counter() - start) * 1000
        return batch

# SPDX-License-Identifier: Apache-2.0
"""MiniMax H3 canonical request validation.

Entry fail-fast for `minimax_h3.request/v1`: every violation raises ValueError
with the offending field path. Output is a normalized canonical dict (frame
indices validated but semantic -1 preserved, nothing else rewritten — prompt passes through verbatim and
conditions order is semantic, never reordered).
"""

from __future__ import annotations

import math
from collections.abc import Mapping, Sequence
from typing import Any

from sglang.multimodal_gen.configs.utils import optional_positive_finite_float
from sglang.multimodal_gen.runtime.pipelines_core.stages.model_specific_stages.minimax_h3.constants import (
    MINIMAX_H3_MAX_DURATION_SECONDS,
    MINIMAX_H3_MIN_DURATION_SECONDS,
    MINIMAX_H3_RECOMMENDED_SHORT_EDGE,
    MINIMAX_H3_SUPPORTED_FPS,
    warn_unverified_short_edge,
)
from sglang.multimodal_gen.runtime.pipelines_core.stages.model_specific_stages.minimax_h3.task_profiles import (
    MINIMAX_H3_CONDITION_ROLE_KEYFRAME,
    MINIMAX_H3_CONDITION_ROLE_REFERENCE,
    MINIMAX_H3_FINITE_ASPECT_RATIOS,
    MINIMAX_H3_FL2VA_KEYFRAME_SIGNATURES,
    MINIMAX_H3_TASK_FL2VA,
    MINIMAX_H3_TASK_REF2VA,
    MINIMAX_H3_TASK_T2VA,
    MiniMaxH3TaskProfile,
    canonical_minimax_h3_task,
    minimax_h3_task_profile,
)
from sglang.multimodal_gen.runtime.pipelines_core.stages.model_specific_stages.minimax_h3.time_request import (
    minimax_h3_align_frame_count,
)

MINIMAX_H3_REQUEST_SCHEMA = "minimax_h3.request/v1"
MINIMAX_H3_MAX_SIGNED_SEED = (1 << 63) - 1
_ALLOWED_CONDITION_KEYS = frozenset(
    {"type", "uri", "role", "frame_index", "start_time_seconds"}
)


def _require_str(value: Any, path: str) -> str:
    if not isinstance(value, str) or value == "":
        raise ValueError(f"{path} must be a non-empty string")
    return value


def _require_int(value: Any, path: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{path} must be an integer")
    return value


def _optional_nonnegative_finite_float(value: Any, path: str) -> float | None:
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{path} must be a number")
    normalized = float(value)
    if not math.isfinite(normalized) or normalized < 0.0:
        raise ValueError(f"{path} must be a non-negative finite number")
    return normalized


def _validate_target(target: Any, *, profile: MiniMaxH3TaskProfile) -> dict[str, Any]:
    path = "target"
    if not isinstance(target, Mapping):
        raise ValueError(f"{path} is required and must be an object")
    # The canonical target has a deliberately small projection.  Transport
    # compatibility keys are ignored; only these three declared values are
    # validated and emitted below.
    short_edge = _require_int(target.get("short_edge"), f"{path}.short_edge")
    if short_edge <= 0:
        raise ValueError(f"{path}.short_edge must be positive, got {short_edge}")
    if short_edge != MINIMAX_H3_RECOMMENDED_SHORT_EDGE:
        # Same guard the resolver applies. Without it the recommended value warns
        # that it is "outside the verified configuration", naming itself as the
        # verified one.
        warn_unverified_short_edge(short_edge)
    aspect_ratio = _require_str(target.get("aspect_ratio"), f"{path}.aspect_ratio")
    if profile.aspect_ratio_forced_auto and aspect_ratio != "auto":
        raise ValueError(
            f'{path}.aspect_ratio must be "auto" for task {profile.task!r}, '
            f"got {aspect_ratio!r}"
        )
    has_duration = target.get("duration_seconds") is not None
    if (
        profile.task in {MINIMAX_H3_TASK_T2VA, MINIMAX_H3_TASK_REF2VA}
        and aspect_ratio != "auto"
        and aspect_ratio not in MINIMAX_H3_FINITE_ASPECT_RATIOS
    ):
        raise ValueError(
            f"{path}.aspect_ratio for task {profile.task!r} must be 'auto' or "
            f"one of {list(MINIMAX_H3_FINITE_ASPECT_RATIOS)!r}, got "
            f"{aspect_ratio!r}"
        )
    if not has_duration:
        if not profile.duration_from_audio_reference:
            raise ValueError(f"{path}.duration_seconds is required")
        # ref2va: duration may derive from a reference audio; the
        # audio-condition presence is enforced after conditions validate.
    out: dict[str, Any] = {
        "short_edge": short_edge,
        "aspect_ratio": aspect_ratio,
    }
    if has_duration:
        duration = target["duration_seconds"]
        if isinstance(duration, bool) or not isinstance(duration, (int, float)):
            raise ValueError(f"{path}.duration_seconds must be a number")
        if duration <= 0:
            raise ValueError(f"{path}.duration_seconds must be positive")
        if not (
            MINIMAX_H3_MIN_DURATION_SECONDS
            <= float(duration)
            <= MINIMAX_H3_MAX_DURATION_SECONDS
        ):
            raise ValueError(
                f"{path}.duration_seconds must be in "
                f"[{MINIMAX_H3_MIN_DURATION_SECONDS:g}, "
                f"{MINIMAX_H3_MAX_DURATION_SECONDS:g}], got {duration}"
            )
        out["duration_seconds"] = float(duration)
    return out


def _validate_conditions(
    conditions: Any,
    *,
    profile: MiniMaxH3TaskProfile,
    frame_count: int | None,
) -> list[dict[str, Any]]:
    path = "conditions"
    if conditions is None:
        conditions = []
    if not isinstance(conditions, Sequence) or isinstance(conditions, (str, bytes)):
        raise ValueError(f"{path} must be a list")

    if not profile.conditions_required:
        if len(conditions) > 0:
            raise ValueError(
                f"{path} must be empty for task {profile.task!r} "
                f"(got {len(conditions)} entries)"
            )
        return []
    if len(conditions) == 0:
        raise ValueError(
            f"{path} requires at least one entry for task {profile.task!r}"
        )
    if (
        profile.min_condition_count is not None
        and len(conditions) < profile.min_condition_count
    ):
        raise ValueError(
            f"{path} requires at least {profile.min_condition_count} entries "
            f"for task {profile.task!r}, got {len(conditions)}"
        )
    if (
        profile.max_condition_count is not None
        and len(conditions) > profile.max_condition_count
    ):
        raise ValueError(
            f"{path} allows at most {profile.max_condition_count} entries "
            f"for task {profile.task!r}, got {len(conditions)}"
        )

    aligned_frame_count = (
        minimax_h3_align_frame_count(frame_count) if frame_count is not None else None
    )
    normalized: list[dict[str, Any]] = []
    seen_frame_indices: dict[int, int] = {}
    for index, cond in enumerate(conditions):
        cpath = f"{path}[{index}]"
        if not isinstance(cond, Mapping):
            raise ValueError(f"{cpath} must be an object")
        unknown = set(cond) - _ALLOWED_CONDITION_KEYS
        if unknown:
            raise ValueError(f"{cpath} has unknown fields: {sorted(unknown)}")
        role = _require_str(cond.get("role"), f"{cpath}.role")
        if role not in (
            MINIMAX_H3_CONDITION_ROLE_KEYFRAME,
            MINIMAX_H3_CONDITION_ROLE_REFERENCE,
        ):
            raise ValueError(
                f"{cpath}.role must be keyframe or reference, got {role!r}"
            )
        cond_type = _require_str(cond.get("type"), f"{cpath}.type")
        try:
            rule = profile.rule_for(role=role, condition_type=cond_type)
        except ValueError as exc:
            raise ValueError(f"{cpath}: {exc}") from exc
        uri = _require_str(cond.get("uri"), f"{cpath}.uri")

        entry: dict[str, Any] = {"type": cond_type, "uri": uri, "role": role}
        if rule.requires_frame_index:
            frame_index = _require_int(cond.get("frame_index"), f"{cpath}.frame_index")
            if aligned_frame_count is None:
                raise ValueError(
                    f"{cpath}.frame_index requires a resolved target duration"
                )
            if frame_index == -1:
                resolved = aligned_frame_count - 1
            elif 0 <= frame_index < aligned_frame_count:
                resolved = frame_index
            else:
                raise ValueError(
                    f"{cpath}.frame_index must be -1 or in "
                    f"[0, {aligned_frame_count}) after 17n+5 frame alignment, "
                    f"got {frame_index}"
                )
            if resolved in seen_frame_indices:
                raise ValueError(
                    f"{cpath}.frame_index resolves to {resolved}, already "
                    f"bound by conditions[{seen_frame_indices[resolved]}]"
                )
            seen_frame_indices[resolved] = index
            # Preserve the request-level semantic index.  In particular, -1 is
            # the canonical last-frame sentinel; the resolved pixel frame is
            # carried separately by MiniMaxH3ResolvedPlan.
            entry["frame_index"] = frame_index
        elif cond.get("frame_index") is not None:
            raise ValueError(f"{cpath}.frame_index is not allowed for role={role!r}")
        start_time_seconds = _optional_nonnegative_finite_float(
            cond.get("start_time_seconds"), f"{cpath}.start_time_seconds"
        )
        if start_time_seconds is not None:
            if cond_type not in {"video", "video_audio"}:
                raise ValueError(
                    f"{cpath}.start_time_seconds is only allowed for video "
                    "or video_audio references"
                )
            entry["start_time_seconds"] = start_time_seconds
        normalized.append(entry)
    return normalized


def _validate_keyframe_conditions(
    conditions: Sequence[Mapping[str, Any]], *, task: str
) -> None:
    """Enforce the shared first/last-frame contract after schema validation."""

    keyframes = [
        condition
        for condition in conditions
        if condition["role"] == MINIMAX_H3_CONDITION_ROLE_KEYFRAME
    ]
    frame_indices = tuple(condition.get("frame_index") for condition in keyframes)
    if frame_indices not in MINIMAX_H3_FL2VA_KEYFRAME_SIGNATURES:
        raise ValueError(
            f"conditions for task {task!r} must include one or two ordered "
            "image/keyframe entries with frame_index [0], [-1], or [0, -1], "
            f"got {list(frame_indices)!r}"
        )
    if task == MINIMAX_H3_TASK_REF2VA and not any(
        condition["role"] == MINIMAX_H3_CONDITION_ROLE_REFERENCE
        for condition in conditions
    ):
        raise ValueError(
            "ref2va keyframes require at least one reference condition; "
            "use task 'fl2va' for keyframe-only generation"
        )


def minimax_h3_validate_canonical_request(
    *,
    task: Any,
    prompt: Any,
    conditions: Any,
    target: Any,
    flow_shift: Any = None,
    audio_flow_shift: Any = None,
    seed: Any = None,
    **_extra_kwargs: Any,
) -> dict[str, Any]:
    """Validate and normalize a `minimax_h3.request/v1` canonical request.

    Returns the normalized canonical dict; raises ValueError with a field
    path on any violation. Conditions order is preserved (it is semantic:
    prompt ordinal labels reference it). seed=0 is a legal value.
    """
    # Accept transport wrappers and compatibility kwargs at this boundary, but
    # never copy them into the canonical request.
    del _extra_kwargs
    # Normalize the task name before profile lookup so offline callers match
    # the adapter behaviour.
    task_name = canonical_minimax_h3_task(_require_str(task, "task"))
    profile = minimax_h3_task_profile(task_name)
    prompt_text = _require_str(prompt, "prompt")

    normalized_target = _validate_target(target, profile=profile)
    requested_frame_count = None
    if normalized_target.get("duration_seconds") is not None:
        requested_frame_count = int(
            round(
                float(normalized_target["duration_seconds"]) * MINIMAX_H3_SUPPORTED_FPS
            )
        )
    normalized_conditions = _validate_conditions(
        conditions,
        profile=profile,
        frame_count=requested_frame_count,
    )
    if profile.task == MINIMAX_H3_TASK_FL2VA:
        _validate_keyframe_conditions(normalized_conditions, task=profile.task)
    elif profile.task == MINIMAX_H3_TASK_REF2VA and any(
        condition["role"] == MINIMAX_H3_CONDITION_ROLE_KEYFRAME
        for condition in normalized_conditions
    ):
        _validate_keyframe_conditions(normalized_conditions, task=profile.task)
    # ref2va accepts ordered reference streams and, for hybrid checkpoints,
    # one first/last keyframe signature. Type admission is handled by the task
    # profile; temporal ambiguity is validated later when target duration is
    # omitted.
    if not profile.video_reference_supported:
        for index, cond in enumerate(normalized_conditions):
            if cond["type"] in ("video", "video_audio"):
                raise ValueError(
                    f"conditions[{index}]: video references are not supported "
                    f"in v1 for task {profile.task!r} (image/audio only)"
                )
    if normalized_target.get("duration_seconds") is None:
        # Only reachable for duration_from_audio_reference profiles.
        duration_sources = [
            cond
            for cond in normalized_conditions
            if cond["type"] in ("audio", "video", "video_audio")
        ]
        if not duration_sources:
            raise ValueError(
                "target.duration_seconds is required, or exactly one "
                "audio reference to derive duration from (including "
                f"video/video_audio soundtracks; task {profile.task!r})"
            )
        if len(duration_sources) > 1:
            raise ValueError(
                "target.duration_seconds is required when multiple "
                "audio-bearing references are provided"
            )

    canonical: dict[str, Any] = {
        "schema": MINIMAX_H3_REQUEST_SCHEMA,
        "task": task_name,
        "prompt": prompt_text,
        "conditions": normalized_conditions,
        "target": normalized_target,
    }
    normalized_flow_shift = optional_positive_finite_float(flow_shift, "flow_shift")
    normalized_audio_flow_shift = optional_positive_finite_float(
        audio_flow_shift, "audio_flow_shift"
    )
    if normalized_flow_shift is not None:
        canonical["flow_shift"] = normalized_flow_shift
    if normalized_audio_flow_shift is not None:
        canonical["audio_flow_shift"] = normalized_audio_flow_shift
    if seed is not None:
        normalized_seed = _require_int(seed, "seed")
        if normalized_seed < 0:
            raise ValueError(f"seed must be non-negative, got {normalized_seed}")
        if normalized_seed > MINIMAX_H3_MAX_SIGNED_SEED:
            raise ValueError(
                f"seed must not exceed the signed int64 maximum, got {normalized_seed}"
            )
        canonical["seed"] = normalized_seed
    return canonical


__all__ = [
    "MINIMAX_H3_REQUEST_SCHEMA",
    "MINIMAX_H3_MAX_SIGNED_SEED",
    "MINIMAX_H3_SUPPORTED_FPS",
    "minimax_h3_validate_canonical_request",
]

